/** Native Nth Nota AI studio: a quiet reading surface with a fixed, keyboard-aware composer. */
@android.annotation.SuppressLint("ViewConstructor")
final class NotaChatView extends LinearLayout {
    interface Host { void send(String text); void stop(); void changedCloud(boolean enabled); void menu(); void close(); }
    final EditText question; final Button send; TextView answer; LinearLayout suggestions;
    private final Host host; private final SharedPreferences draft,storage; private final NotaConversation conversations;
    private final ScrollView scroll; private final LinearLayout transcript; private final TextView status,chatTitle; private final Switch cloud;
    private final Button web,jump; private final LinearLayout composer,breadcrumb;
    private String pending; private boolean busy,search,syncingCloud;
    NotaChatView(Context c,SharedPreferences draft,Host host){
        super(c);this.host=host;this.draft=draft;storage=c.getSharedPreferences("nota_conversations",Context.MODE_PRIVATE);conversations=new NotaConversation(storage.getString("document",""));setOrientation(VERTICAL);search=draft.getBoolean("nota_web_always",false);setTag("nota-ai-studio");
        LinearLayout header=Ui.row(c);header.setPadding(0,0,0,Ui.dp(c,10));NotaDesign.Mark mark=new NotaDesign.Mark(c);header.addView(mark,new LayoutParams(Ui.dp(c,32),Ui.dp(c,32)));
        LinearLayout brand=Ui.column(c);brand.setPadding(Ui.dp(c,10),0,0,0);TextView name=label("Nth Nota AI",17,NotaDesign.TEXT);name.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));brand.addView(name);TextView sub=label("A little space to think.",11,NotaDesign.MUTED);sub.setPadding(0,Ui.dp(c,3),0,0);brand.addView(sub);header.addView(brand,new LayoutParams(0,-2,1));
        header.addView(icon("compose","New conversation",this::newChat),new LayoutParams(Ui.dp(c,44),Ui.dp(c,44)));header.addView(icon("more","Conversation menu",host::menu),new LayoutParams(Ui.dp(c,44),Ui.dp(c,44)));header.addView(icon("close","Close Nth Nota AI",host::close),new LayoutParams(Ui.dp(c,44),Ui.dp(c,44)));addView(header,new LayoutParams(-1,-2));
        breadcrumb=Ui.row(c);chatTitle=label("",12,NotaDesign.MUTED);chatTitle.setSingleLine(true);chatTitle.setEllipsize(TextUtils.TruncateAt.END);breadcrumb.addView(chatTitle,new LayoutParams(0,-2,1));Button history=NotaDesign.action(c,"Recent chats",this::recent);history.setTag("nota-history");breadcrumb.addView(history,new LayoutParams(-2,Ui.dp(c,44)));addView(breadcrumb,new LayoutParams(-1,-2));
        View rule=new View(c);rule.setBackgroundColor(NotaDesign.LINE);addView(rule,new LayoutParams(-1,Ui.dp(c,1)));
        FrameLayout viewport=new FrameLayout(c);scroll=new ScrollView(c);scroll.setFillViewport(true);scroll.setClipToPadding(false);scroll.setVerticalScrollBarEnabled(false);scroll.setTag("nota-transcript");transcript=Ui.column(c);transcript.setPadding(Ui.dp(c,2),Ui.dp(c,20),Ui.dp(c,2),Ui.dp(c,24));scroll.addView(transcript,new ScrollView.LayoutParams(-1,-2));viewport.addView(scroll,new FrameLayout.LayoutParams(-1,-1));
        jump=NotaDesign.action(c,"↓  Latest",this::bottom);jump.setTag("nota-latest");jump.setContentDescription("Jump to latest message");jump.setBackground(Ui.touch(c,NotaDesign.surface(c,NotaDesign.SURFACE,22),22));jump.setElevation(Ui.dp(c,5));FrameLayout.LayoutParams jp=new FrameLayout.LayoutParams(-2,Ui.dp(c,44),Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);jp.bottomMargin=Ui.dp(c,8);viewport.addView(jump,jp);jump.setVisibility(GONE);scroll.setOnScrollChangeListener((View.OnScrollChangeListener)(v,x,y,oldX,oldY)->updateJump());addView(viewport,new LayoutParams(-1,0,1));
        composer=Ui.column(c);composer.setTag("nota-composer");composer.setPadding(Ui.dp(c,12),Ui.dp(c,8),Ui.dp(c,8),Ui.dp(c,6));composer.setBackground(NotaDesign.surface(c,NotaDesign.SURFACE,24));
        LinearLayout input=Ui.row(c);input.setGravity(Gravity.BOTTOM);question=new EditText(c);question.setTextSize(16);question.setTextColor(NotaDesign.TEXT);question.setHintTextColor(NotaDesign.MUTED);question.setHint("Message Nth Nota AI");question.setContentDescription("Message Nth Nota AI");question.setBackgroundColor(android.graphics.Color.TRANSPARENT);question.setPadding(Ui.dp(c,4),Ui.dp(c,10),Ui.dp(c,10),Ui.dp(c,12));question.setMinLines(1);question.setMaxLines(4);question.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES|InputType.TYPE_TEXT_FLAG_MULTI_LINE);question.setImeOptions(EditorInfo.IME_ACTION_SEND);question.setFilters(new InputFilter[]{new InputFilter.LengthFilter(2000)});input.addView(question,new LayoutParams(0,-2,1));send=NotaDesign.action(c,"↑",()->{if(busy)host.stop();else host.send(question.getText().toString());});send.setTextSize(24);send.setTextColor(NotaDesign.CANVAS);send.setPadding(0,0,0,0);send.setTag("nota-send");input.addView(send,new LayoutParams(Ui.dp(c,44),Ui.dp(c,44)));composer.addView(input,new LayoutParams(-1,-2));
        LinearLayout modes=Ui.row(c);cloud=new Switch(c);cloud.setText("Cloud questions");cloud.setContentDescription("Cloud questions for Nth Nota AI");cloud.setTextColor(NotaDesign.MUTED);cloud.setTextSize(12);cloud.setMinHeight(Ui.dp(c,44));cloud.setThumbTintList(android.content.res.ColorStateList.valueOf(NotaDesign.ACCENT));cloud.setChecked(draft.getBoolean("cloud_ai",false));modes.addView(cloud,new LayoutParams(0,-2,1));web=NotaDesign.action(c,search?"Web · Always":"Web · Auto",()->{search=!search;draft.edit().putBoolean("nota_web_always",search).apply();updateWeb();});web.setTag("nota-search-mode");modes.addView(web,new LayoutParams(-2,Ui.dp(c,44)));composer.addView(modes);addView(composer,new LayoutParams(-1,-2));
        cloud.setOnCheckedChangeListener((button,enabled)->{if(syncingCloud)return;if(enabled&&!draft.getBoolean("nota_chat_consent",false)){cloud.setChecked(false);android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(c).setTitle("Allow Nth Nota AI cloud questions?").setMessage("Your message and recent cloud conversation turns are sent to Nth Nota AI's service. Search providers may receive relevant search terms, and page readers may receive links you ask the AI to read. Launcher questions can include current setting values. Current weather uses Open-Meteo with a city or your permitted approximate location. Weather lookups stay out of AI chat context. Notes, cards and your app list are not attached. Conversations stay on this device. You can switch cloud questions off at any time.").setNegativeButton("Keep off",null).setPositiveButton("Enable cloud",(d,w)->{draft.edit().putBoolean("nota_chat_consent",true).apply();cloud.setChecked(true);}).create();Ui.themeDialog(dialog);return;}host.changedCloud(enabled);status();});
        status=label("",10,NotaDesign.MUTED);status.setGravity(Gravity.CENTER);status.setPadding(0,Ui.dp(c,8),0,0);status.setAccessibilityLiveRegion(ACCESSIBILITY_LIVE_REGION_POLITE);addView(status,new LayoutParams(-1,-2));
        question.setText(draft.getString("nota_draft",""));question.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void afterTextChanged(Editable e){draft.edit().putString("nota_draft",e.toString()).apply();updateSend();}public void onTextChanged(CharSequence s,int st,int before,int count){}});question.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_SEND&&!busy){host.send(question.getText().toString());return true;}return false;});render(false);status();updateWeb();if(!conversations.current().turns.isEmpty())scroll.post(this::latestReply);
    }
    private Button icon(String glyph,String description,Runnable run){Button b=Ui.icon(getContext(),glyph,description,run);b.setTag("nota-"+glyph);return b;}
    private void persist(){storage.edit().putString("document",conversations.save()).apply();}
    JSONArray context(){return conversations.current().context();}
    boolean alwaysSearch(){return search;}
    boolean busy(){return busy;}
    private void status(){status.setText(busy?"Working on your reply · Stop at any time":cloud.isChecked()?"Cloud on · Check important details against sources":"Cloud off · Launcher commands work on this device");updateWeb();}
    private void updateWeb(){web.setText(search?"Web · Always":"Web · Auto");web.setContentDescription(search?"Web search always; tap for automatic":"Web search automatic; tap for always");web.setTextColor(search?NotaDesign.ACCENT:NotaDesign.MUTED);}
    private void updateSend(){boolean ready=busy||!question.getText().toString().trim().isEmpty();send.setEnabled(ready);send.setAlpha(ready?1:.45f);send.setText(busy?"■":"↑");send.setTextSize(busy?17:24);send.setContentDescription(busy?"Stop reply":"Send to Nth Nota AI");send.setBackground(Ui.touch(getContext(),NotaDesign.surface(getContext(),NotaDesign.ACCENT,16),16));}
    void syncCloud(){syncingCloud=true;cloud.setChecked(draft.getBoolean("cloud_ai",false));syncingCloud=false;status();}
    void draft(String text){question.setText(text);question.setSelection(question.length());question.requestFocus();}
    void begin(String text){pending=text;busy=true;question.setText("");render(true);status();}
    void progress(String text){if(busy&&answer!=null){boolean follow=nearBottom();answer.setText(text);if(follow)bottom();}}
    void finish(LiveAnswer reply,boolean context){if(pending==null)return;boolean follow=nearBottom();conversations.append(pending,reply,context);pending=null;busy=false;persist();render(follow);status();}
    void stop(){if(pending!=null)finish(LiveAnswer.plain("Reply stopped. You can send another message whenever you’re ready.","Stopped"),false);}
    void newChat(){host.stop();conversations.newChat();persist();question.setText("");render(false);scroll.scrollTo(0,0);status();}
    void recent(){host.stop();Context c=getContext();LinearLayout sheet=Ui.column(c);sheet.setPadding(Ui.dp(c,12),Ui.dp(c,8),Ui.dp(c,12),0);TextView local=label("Saved only on this device",12,NotaDesign.MUTED);local.setPadding(Ui.dp(c,10),0,0,Ui.dp(c,10));sheet.addView(local);ScrollView list=new ScrollView(c);LinearLayout rows=Ui.column(c);list.addView(rows);sheet.addView(list,new LayoutParams(-1,Ui.dp(c,Math.min(340,conversations.chats.size()*64))));android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(c).setTitle("Recent conversations").setView(sheet).setNegativeButton("Close",null).create();
        for(NotaConversation.Chat saved:conversations.chats){String title=(saved.id.equals(conversations.current().id)?"●  ":"")+saved.title();Button row=NotaDesign.action(c,title+"\n"+(saved.turns.isEmpty()?"No messages yet":saved.turns.size()+" exchanges · "+java.text.DateFormat.getDateInstance(java.text.DateFormat.MEDIUM).format(new java.util.Date(saved.updated))),()->{host.stop();conversations.select(saved.id);persist();question.setText("");render(true);status();dialog.dismiss();});row.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);row.setTextColor(saved.id.equals(conversations.current().id)?NotaDesign.ACCENT:NotaDesign.TEXT);rows.addView(row,new LayoutParams(-1,-2));}Ui.themeDialog(dialog);
    }
    void delete(){Ui.themeDialog(new android.app.AlertDialog.Builder(getContext()).setTitle("Delete this conversation?").setMessage("This removes its messages from this device.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->{host.stop();conversations.deleteCurrent();persist();question.setText("");render(false);status();}).create());}
    private TextView label(String text,int size,int color){return NotaReplyView.text(getContext(),text,size,color);}
    private void render(boolean follow){
        int previous=scroll.getScrollY();answer=null;suggestions=null;transcript.removeAllViews();chatTitle.setText(conversations.current().title());
        if(conversations.current().turns.isEmpty()&&pending==null)welcome();
        for(NotaConversation.Turn t:conversations.current().turns){user(t.question);assistant(t.answer,t.question,false);}
        if(pending!=null){user(pending);assistant(LiveAnswer.plain("Thinking about your question", "Nth Nota AI"),pending,true);}
        updateSend();scroll.post(()->{if(follow&&pending==null)latestReply();else scroll.scrollTo(0,follow?Math.max(0,transcript.getHeight()-scroll.getHeight()):previous);updateJump();});
    }
    private void welcome(){
        Context c=getContext();LinearLayout welcome=Ui.column(c);welcome.setGravity(Gravity.CENTER);welcome.setPadding(Ui.dp(c,4),Ui.dp(c,14),Ui.dp(c,4),Ui.dp(c,14));welcome.addView(new NotaDesign.Mark(c),new LayoutParams(Ui.dp(c,62),Ui.dp(c,62)));
        LinearLayout intro=Ui.column(c);
        intro.setGravity(Gravity.CENTER);
        intro.setPadding(Ui.dp(c,16),Ui.dp(c,8),Ui.dp(c,16),Ui.dp(c,8));
        intro.setBackground(NotaDesign.surface(c,0xAA181B24,18));
        LayoutParams introParams=new LayoutParams(-2,-2);
        introParams.setMargins(0,Ui.dp(c,12),0,Ui.dp(c,16));
        welcome.addView(intro,introParams);
        TextView heading=label("Where shall we begin?",29,NotaDesign.TEXT);heading.setGravity(Gravity.CENTER);heading.setTypeface(Typeface.create("serif",Typeface.NORMAL));intro.addView(heading,new LayoutParams(-2,-2));TextView detail=label("A question. A fresh idea. Your next step.",13,NotaDesign.MUTED);detail.setGravity(Gravity.CENTER);detail.setPadding(0,Ui.dp(c,6),0,0);intro.addView(detail);
        String[][] prompts={{"Explore an idea","Why does the sky change color at sunset?","Understand something new"},{"Make something","Help me write a warm thank-you message.","Find the words you need"},{"Plan my day","Help me plan a relaxed, productive day.","Turn a thought into a plan"},{"Shape my desktop","How can I make my desktop feel calmer?","Make this space your own"}};
        for(int row=0;row<2;row++){LinearLayout pair=Ui.row(c);pair.setGravity(Gravity.TOP);for(int column=0;column<2;column++){String[] prompt=prompts[row*2+column];Button b=NotaDesign.action(c,prompt[0]+"  ↗\n"+prompt[2],()->draft(prompt[1]));b.setTag("nota-prompt:"+(row*2+column));b.setContentDescription(prompt[0]+"  ↗");SpannableString card=new SpannableString(prompt[0]+"  ↗\n"+prompt[2]);int detailStart=card.toString().indexOf('\n')+1;card.setSpan(new android.text.style.ForegroundColorSpan(NotaDesign.MUTED),detailStart,card.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);card.setSpan(new android.text.style.RelativeSizeSpan(.92f),detailStart,card.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);card.setSpan(new android.text.style.TypefaceSpan("sans-serif"),detailStart,card.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);b.setText(card);b.setMinHeight(Ui.dp(c,80));b.setMinimumHeight(Ui.dp(c,80));b.setTextColor(NotaDesign.TEXT);b.setTextSize(13);b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setBackground(Ui.touch(c,NotaDesign.surface(c,0xDF20242F,16),16));b.setPadding(Ui.dp(c,12),Ui.dp(c,13),Ui.dp(c,10),Ui.dp(c,13));LayoutParams bp=new LayoutParams(0,-2,1);bp.setMargins(0,0,Ui.dp(c,column==0?8:0),Ui.dp(c,8));pair.addView(b,bp);}welcome.addView(pair,new LayoutParams(-1,-2));}transcript.addView(welcome,new LayoutParams(-1,-2));
    }
    private void user(String text){Context c=getContext();TextView user=label(text,16,NotaDesign.TEXT);user.setTextIsSelectable(true);user.setLineSpacing(Ui.dp(c,3),1.03f);user.setPadding(Ui.dp(c,16),Ui.dp(c,13),Ui.dp(c,16),Ui.dp(c,13));user.setBackground(NotaDesign.surface(c,0xE1303443,20));LayoutParams p=new LayoutParams(-2,-2);p.gravity=Gravity.END;p.leftMargin=Ui.dp(c,32);p.topMargin=Ui.dp(c,6);p.bottomMargin=Ui.dp(c,24);transcript.addView(user,p);}
    private void assistant(LiveAnswer reply,String query,boolean pendingReply){
        Context c=getContext();LinearLayout block=Ui.column(c);
        int inset=Ui.dp(c,12);
        block.setPadding(inset,inset,inset,inset);
        block.setBackground(NotaDesign.surface(c,0xC4181B24,20));
        LinearLayout heading=Ui.row(c);heading.addView(new NotaDesign.Mark(c),new LayoutParams(Ui.dp(c,23),Ui.dp(c,23)));TextView name=label("Nth Nota AI",12,NotaDesign.ACCENT);name.setPadding(Ui.dp(c,8),0,0,0);name.setTypeface(null,Typeface.BOLD);heading.addView(name,new LayoutParams(0,-2,1));LayoutParams hp=new LayoutParams(-1,Ui.dp(c,32));hp.bottomMargin=Ui.dp(c,8);block.addView(heading,hp);
        if(pendingReply){answer=label(reply.text,16,NotaDesign.MUTED);answer.setAccessibilityLiveRegion(ACCESSIBILITY_LIVE_REGION_POLITE);answer.setTag("nota-answer");block.addView(answer,new LayoutParams(-1,-2));}
        else{NotaReplyView prose=new NotaReplyView(c,reply.text);answer=prose.primary;answer.setTag("nota-answer");block.addView(prose,new LayoutParams(-1,-2));}
        suggestions=Ui.column(c);block.addView(suggestions);if(!reply.sources.isEmpty()){TextView sources=label("SOURCES  ·  "+reply.sources.size(),10,NotaDesign.MUTED);sources.setLetterSpacing(.12f);sources.setPadding(0,Ui.dp(c,10),0,Ui.dp(c,8));suggestions.addView(sources);int i=0;for(LiveAnswer.Source source:reply.sources){String domain=android.net.Uri.parse(source.url).getHost();Button link=NotaDesign.action(c,(++i)+"  "+source.title+"  ↗\n"+(domain==null?"Public source":domain.replaceFirst("^www\\.","")),()->open(source.url));link.setTextColor(NotaDesign.TEXT);link.setTextSize(12);link.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);link.setBackground(Ui.touch(c,NotaDesign.surface(c,0xFF20242E,12),12));link.setTag("nota-source:"+i);link.setContentDescription("Open source: "+source.title);LayoutParams lp=new LayoutParams(-1,-2);lp.bottomMargin=Ui.dp(c,6);suggestions.addView(link,lp);}}
        if(reply.searchFallback){Button fallback=NotaDesign.action(c,"Search the web  ↗",()->open("https://www.google.com/search?q="+android.net.Uri.encode(query)));fallback.setTag("nota-web-search");suggestions.addView(fallback,new LayoutParams(-1,-2));}
        if(!pendingReply){LinearLayout actions=Ui.row(c);Button copy=NotaDesign.action(c,"Copy",()->NotaReplyView.copy(c,reply.text));copy.setContentDescription("Copy Nth Nota AI reply");actions.addView(copy,new LayoutParams(-2,Ui.dp(c,44)));Button reuse=NotaDesign.action(c,"Edit question",()->draft(query));reuse.setContentDescription("Edit question without sending");actions.addView(reuse,new LayoutParams(-2,Ui.dp(c,44)));TextView meta=label(reply.kind+(reply.checkedAt>0?" · "+java.text.DateFormat.getTimeInstance(java.text.DateFormat.SHORT).format(new java.util.Date(reply.checkedAt)):""),10,NotaDesign.MUTED);meta.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);if(reply.checkedAt>0)meta.setContentDescription(reply.kind+" · "+java.text.DateFormat.getDateTimeInstance().format(new java.util.Date(reply.checkedAt)));actions.addView(meta,new LayoutParams(0,-2,1));block.addView(actions,new LayoutParams(-1,-2));}
        LayoutParams p=new LayoutParams(-1,-2);p.bottomMargin=Ui.dp(c,24);transcript.addView(block,p);
    }
    private void open(String url){if(!LiveAnswer.safeLink(url))return;try{getContext().startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(url)));}catch(ActivityNotFoundException|SecurityException missing){Toast.makeText(getContext(),"A browser is unavailable.",Toast.LENGTH_SHORT).show();}}
    private void latestReply(){View block=transcript.getChildAt(transcript.getChildCount()-1);int maximum=Math.max(0,transcript.getHeight()-scroll.getHeight());scroll.scrollTo(0,block==null?0:Math.min(maximum,Math.max(0,block.getTop()-Ui.dp(getContext(),8))));updateJump();}
    private boolean nearBottom(){return transcript.getHeight()-scroll.getHeight()-scroll.getScrollY()<Ui.dp(getContext(),90);}
    @Override protected void onSizeChanged(int w,int h,int oldw,int oldh){super.onSizeChanged(w,h,oldw,oldh);boolean compact=h<Ui.dp(getContext(),390);breadcrumb.setVisibility(compact?GONE:VISIBLE);status.setVisibility(compact?GONE:VISIBLE);transcript.setPadding(Ui.dp(getContext(),2),Ui.dp(getContext(),20),Ui.dp(getContext(),2),Ui.dp(getContext(),compact?8:24));}
    private void updateJump(){jump.setVisibility(!nearBottom()&&!conversations.current().turns.isEmpty()?VISIBLE:GONE);}
    private void bottom(){scroll.post(()->{scroll.smoothScrollTo(0,Math.max(0,transcript.getHeight()-scroll.getHeight()));updateJump();});}
}
